// THROWAWAY (ab/c1-harness-h1h2h4h5-20261105, not for merge). Pins the registry of the v1.6.0 attribution campaign's arm columns (plan 2026-11-04 Revision 2, H1/H2), generated by
// arm-gen.py: main = servers/celeris as pinned (busy poll at the celeris default, OFF), bpon = the SAME module with the column env PROBATORIUM_SOCKET_BUSY_POLL=50us, v1511 =
// servers/celeris_v1511. Two targets: c1arm (msr1, arm64: 64 columns main 32 / bpon 16 / v1511 16, AB_IRQ_VECTOR_CPU=1) and c2x86 (msa2-server, amd64: 16 columns main 8 / bpon 8, no
// AB_IRQ_VECTOR_CPU). The pin of main and bpon is the celeris require of servers/celeris/go.mod, read here, so H0's repin fails this test until arm-gen.py is run again.
const (
	knobEnv   = "PROBATORIUM_SOCKET_BUSY_POLL"
	knobValue = "50us"
)

type c1Target struct {
	prefix  string
	counts  map[string]int // arm -> columns
	mult    map[string]int // arm -> slots per block
	baseEnv map[string]string
}

var c1Targets = []c1Target{
	{"c1arm", map[string]int{"main": 32, "bpon": 16, "v1511": 16}, map[string]int{"main": 2, "bpon": 1, "v1511": 1}, map[string]string{"AB_IRQ_VECTOR_CPU": "1"}},
	{"c2x86", map[string]int{"main": 8, "bpon": 8}, map[string]int{"main": 1, "bpon": 1}, nil},
}

var (
	c1Mod = map[string]string{"main": "celeris", "bpon": "celeris", "v1511": "celeris_v1511"}
	c1FW  = map[string]string{"main": "celeris-pp-main", "bpon": "celeris-pp-bpon", "v1511": "celeris-pp-v1511"}
)

type c1Col struct {
	name, arm string
	seq, rep  int
}

func (tg c1Target) glob() string { return "get-simple-512c/" + tg.prefix + "-*-io512" }

func (tg c1Target) cols(t *testing.T) []c1Col {
	t.Helper()
	re := regexp.MustCompile(`^` + tg.prefix + `-(\d{3})-r(\d+)-(main|bpon|v1511)-io512$`)
	var cols []c1Col
	for name := range servers.Registry {
		if !strings.HasPrefix(name, tg.prefix+"-") {
			continue
		}
		m := re.FindStringSubmatch(name)
		if m == nil {
			t.Errorf("column %s does not match the naming %s-<seq>-r<rep>-<main|bpon|v1511>-io512", name, tg.prefix)
			continue
		}
		seq, _ := strconv.Atoi(m[1])
		rep, _ := strconv.Atoi(m[2])
		cols = append(cols, c1Col{name, m[3], seq, rep})
	}
	sort.Slice(cols, func(i, j int) bool { return cols[i].name < cols[j].name })
	return cols
}

func (tg c1Target) total() int {
	n := 0
	for _, c := range tg.counts {
		n += c
	}
	return n
}

// celerisRequire returns the celeris version a module's go.mod requires.
func celerisRequire(t *testing.T, dir string) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "servers", dir, "go.mod"))
	if err != nil {
		b, err = os.ReadFile(filepath.Join(dir, "go.mod"))
	}
	if err != nil {
		t.Fatal(err)
	}
	m := regexp.MustCompile(`(?m)^\s*github\.com/goceleris/celeris (v\S+)\s*$`).FindStringSubmatch(string(b))
	if m == nil {
		t.Fatalf("%s/go.mod has no celeris require", dir)
	}
	return m[1]
}

func TestC1ArmGlobsSelectOneCellPerColumn(t *testing.T) {
	for _, tg := range c1Targets {
		got := p2Matched(t, tg.glob())
		if len(got) != tg.total() {
			t.Fatalf("%s: the glob selects %d columns, want %d", tg.prefix, len(got), tg.total())
		}
		for c, s := range got {
			if len(s) != 1 {
				t.Errorf("%s: column %s matches %d scenarios %v, want exactly 1", tg.prefix, c, len(s), s)
			}
			if !strings.HasPrefix(c, tg.prefix+"-") || !strings.HasSuffix(c, "-io512") {
				t.Errorf("%s: the glob selects the foreign column %s", tg.prefix, c)
			}
		}
		if !strings.Contains(tg.glob(), "-io512") {
			t.Error("the glob must contain '-io512': benchmark-tier.yml keys the 90 s / 20 s window on that substring")
		}
		// the experiments never mix on one dispatch
		for _, g := range []string{p2Fast, p2Nine} {
			for c := range p2Matched(t, g) {
				if strings.HasPrefix(c, tg.prefix+"-") {
					t.Errorf("the glob %q selects the %s column %s", g, tg.prefix, c)
				}
			}
		}
		for _, other := range c1Targets {
			if other.prefix == tg.prefix {
				continue
			}
			for c := range got {
				if strings.HasPrefix(c, other.prefix+"-") {
					t.Errorf("the %s glob selects the %s column %s", tg.prefix, other.prefix, c)
				}
			}
		}
	}
}

func TestC1ArmLayout(t *testing.T) {
	mainPin := celerisRequire(t, "celeris")
	tw := servers.Registry["celeris-iouring-h1-async"]
	for _, tg := range c1Targets {
		cols := tg.cols(t)
		if len(cols) != tg.total() {
			t.Fatalf("%s: %d columns, want %d", tg.prefix, len(cols), tg.total())
		}
		k := 0
		for _, m := range tg.mult {
			k += m
		}
		blocks := len(cols) / k
		var sched [][]string
		nrep := map[string]int{}
		for i, c := range cols { // sorted name order is the execution order
			if c.seq != 1+i {
				t.Fatalf("%s: sorted column %d is %s, want seq %03d", tg.prefix, i, c.name, 1+i)
			}
			nrep[c.arm]++
			if c.rep != nrep[c.arm] {
				t.Errorf("%s: arm %s replicate %d at seq %d, want %d (the replicate numbers an arm's columns in execution order)", c.name, c.arm, c.rep, c.seq, nrep[c.arm])
			}
			if i%k == 0 {
				sched = append(sched, nil)
			}
			sched[len(sched)-1] = append(sched[len(sched)-1], c.arm)
		}
		for arm, want := range tg.counts {
			if nrep[arm] != want {
				t.Errorf("%s: arm %s has %d columns, want %d", tg.prefix, arm, nrep[arm], want)
			}
		}
		var multiset []string
		for arm, m := range tg.mult {
			for i := 0; i < m; i++ {
				multiset = append(multiset, arm)
			}
		}
		slices.Sort(multiset)
		for b, s := range sched {
			c := slices.Clone(s)
			slices.Sort(c)
			if !slices.Equal(c, multiset) {
				t.Errorf("%s: block %d holds %v, want the multiset %v", tg.prefix, b+1, s, multiset)
			}
		}
		// every arm holds every slot floor(expected)..ceil(expected) times (+-1 when expected is an integer); nobody leads or ends two consecutive blocks
		for arm, m := range tg.mult {
			e := float64(blocks*m) / float64(k)
			lo, hi := int(e), int(e)
			if e != float64(int(e)) {
				hi++
			} else {
				lo--
				hi++
			}
			for pos := 0; pos < k; pos++ {
				n := 0
				for _, s := range sched {
					if s[pos] == arm {
						n++
					}
				}
				if n < lo || n > hi {
					t.Errorf("%s: arm %s holds slot %d in %d of %d blocks, want %d..%d", tg.prefix, arm, pos+1, n, blocks, lo, hi)
				}
			}
		}
		for b := 0; b+1 < blocks; b++ {
			if sched[b][0] == sched[b+1][0] {
				t.Errorf("%s: %s leads blocks %d and %d", tg.prefix, sched[b][0], b+1, b+2)
			}
			if sched[b][k-1] == sched[b+1][k-1] {
				t.Errorf("%s: %s is last in blocks %d and %d", tg.prefix, sched[b][k-1], b+1, b+2)
			}
		}
		// per-column registry facts
		for _, c := range cols {
			a := servers.Registry[c.name]
			gb, ok := a.Bin.(servers.GoBinary)
			if !ok {
				t.Fatalf("%s: Bin is not a GoBinary", c.name)
			}
			if filepath.Base(gb.ModuleDir) != c1Mod[c.arm] {
				t.Errorf("%s: module %s, want servers/%s", c.name, gb.ModuleDir, c1Mod[c.arm])
			}
			if a.Framework != c1FW[c.arm] {
				t.Errorf("%s: framework %q, want %q (never \"celeris\": the report builders stamp the main pin on it)", c.name, a.Framework, c1FW[c.arm])
			}
			wantVer := mainPin
			if c.arm == "v1511" {
				wantVer = servers.BaselineCelerisVersion
				if got := celerisRequire(t, "celeris_v1511"); got != wantVer {
					t.Errorf("servers/celeris_v1511/go.mod requires %s, want %s", got, wantVer)
				}
			}
			if a.FrameworkVersion != wantVer {
				t.Errorf("%s: registry version %s, want %s (the celeris require of servers/%s/go.mod): run arm-gen.py again after a repin", c.name, a.FrameworkVersion, wantVer, c1Mod[c.arm])
			}
			wantEnv := map[string]string{}
			for k, v := range tg.baseEnv {
				wantEnv[k] = v
			}
			if c.arm == "bpon" {
				wantEnv[knobEnv] = knobValue
			}
			if len(wantEnv) == 0 {
				wantEnv = nil
			}
			if !reflect.DeepEqual(a.SUTEnv, wantEnv) {
				t.Errorf("%s: SUTEnv %v, want exactly %v", c.name, a.SUTEnv, wantEnv)
			}
			if a.Engine != tw.Engine || a.Language != tw.Language || a.Capabilities != tw.Capabilities {
				t.Errorf("%s: engine/language/capabilities differ from celeris-iouring-h1-async", c.name)
			}
		}
	}
}

// bpon is the SAME build as main: one module, one -engine, and the columns differ in nothing but the name, the framework label and the one env key.
func TestC1ArmBponIsTheSameBuildAsMain(t *testing.T) {
	for _, tg := range c1Targets {
		var m, b *servers.Adapter
		for _, c := range tg.cols(t) {
			a := servers.Registry[c.name]
			if c.arm == "main" && m == nil {
				m = &a
			}
			if c.arm == "bpon" && b == nil {
				b = &a
			}
		}
		if m == nil || b == nil {
			t.Fatalf("%s: no main or bpon column", tg.prefix)
		}
		norm := *b
		norm.Name, norm.Framework, norm.SUTEnv = m.Name, m.Framework, m.SUTEnv
		if !reflect.DeepEqual(norm, *m) {
			t.Errorf("%s: bpon differs from main in more than Name/Framework/SUTEnv:\nmain %+v\nbpon %+v", tg.prefix, *m, *b)
		}
		if len(b.SUTEnv)-len(m.SUTEnv) != 1 || b.SUTEnv[knobEnv] != knobValue || m.SUTEnv[knobEnv] != "" {
			t.Errorf("%s: main env %v, bpon env %v: bpon must add exactly %s=%s", tg.prefix, m.SUTEnv, b.SUTEnv, knobEnv, knobValue)
		}
	}
}

// The knob the registry sets is the one the adapter reads, and its value means 50 microseconds and survives the SUT env charset (no micro sign).
func TestC1ArmKnobMatchesTheAdapter(t *testing.T) {
	for _, mod := range []string{"celeris", "celeris_v1511"} {
		src, err := os.ReadFile(filepath.Join(mod, "busypoll_knob.go"))
		if err != nil {
			t.Fatal(err)
		}
		if !strings.Contains(string(src), `const busyPollEnv = "`+knobEnv+`"`) {
			t.Errorf("servers/%s/busypoll_knob.go does not read %s", mod, knobEnv)
		}
	}
	d, err := time.ParseDuration(knobValue)
	if err != nil || d != 50*time.Microsecond {
		t.Errorf("%q parses to %v, %v, want 50us", knobValue, d, err)
	}
	if !regexp.MustCompile(`^[A-Za-z0-9_./:@+=-]*$`).MatchString(knobValue) {
		t.Errorf("%q is outside the SUT env value charset", knobValue)
	}
	// the knob file is one file in every module (a mirror cannot drift)
	ref, _ := os.ReadFile("celeris/busypoll_knob.go")
	for _, mod := range []string{"celeris_v1511"} {
		got, _ := os.ReadFile(filepath.Join(mod, "busypoll_knob.go"))
		if string(got) != string(ref) {
			t.Errorf("servers/%s/busypoll_knob.go differs from servers/celeris/busypoll_knob.go", mod)
		}
	}
}
